INSERT OR REPLACE INTO knowledge_items (id,package_id,kind,title,path,category,level,summary,tags,version,status,origin,search_text,updated_at) VALUES ('luau-variables','rdev-luau','lesson','Variables and basic data types','Luau Programming','Luau Programming','Beginner','Store information with local variables and work with strings, numbers and booleans.','luau,variable,string,number,boolean','1.0.0','published','ai-assisted','variables and basic data types store information with local variables and work with strings, numbers and booleans. a **variable** is a named place to keep a value while a script runs. in luau, prefer `local` variables unless a wider scope is genuinely needed. luau also supports compound assignment such as `+=` and interpolated strings written with backticks. example  how it works `playername` holds a string, `coins` a number and `hasjoined` a boolean. `coins += 10` adds ten to the existing value. backtick strings insert values written inside braces. `typeof` reports the type of a value at runtime. common mistakes using unclear names such as `x` or `data` for everything. forgetting `local`, which creates a global variable that other scripts may overwrite. joining a number to a string with `+` instead of `..` or interpolation. `nil` means "no value". reading a variable that was never set gives `nil`, not an error. create variables for a player name, a score and whether a round is active. print all three with one interpolated string, then add 5 to the score and print again.','2026-11-22');
