INSERT OR REPLACE INTO knowledge_items (id,package_id,kind,title,path,category,level,summary,tags,version,status,origin,search_text,updated_at) VALUES ('luau-functions','rdev-luau','lesson','Writing reusable functions','Luau Programming','Luau Programming','Beginner','Group instructions into functions and pass information through parameters and return values.','luau,function,parameter,return','1.0.0','published','ai-assisted','writing reusable functions group instructions into functions and pass information through parameters and return values. functions package instructions so they can be called whenever needed. this removes repetition and gives a script clear structure. **parameters** are inputs; a **return** statement sends a result back to the caller. example  how it works the function accepts two parameters. the `: number` parts are optional type annotations that help tooling catch mistakes. `return` hands the calculated value back. the call passes 50 and 2, so `reward` becomes 100. common mistakes forgetting to `return` when the caller needs a value. writing one huge function that handles unrelated jobs. defining a function after the code that calls it when using `local function`. name functions with verbs such as `calculatereward` or `spawnenemy` so call sites read like sentences. write a function `addbonus(score, bonus)` that returns the new total. call it twice with different values and print both results.','2026-11-22');
INSERT OR REPLACE INTO entry_sources (entry_id,source_id) VALUES ('luau-functions','luau-syntax');
INSERT OR REPLACE INTO knowledge_items (id,package_id,kind,title,path,category,level,summary,tags,version,status,origin,search_text,updated_at) VALUES ('luau-control-flow','rdev-luau','lesson','Decisions and loops','Luau Programming','Luau Programming','Beginner','Use if statements, numeric for loops, while loops and continue to control how code runs.','luau,if,loop,control flow,condition','1.0.0','published','ai-assisted','decisions and loops use if statements, numeric for loops, while loops and continue to control how code runs. control flow decides which code runs and how often. `if` chooses a branch. `for` repeats a known number of times. `while` repeats until a condition becomes false. example  how it works `for i = 1, 10` counts from 1 to 10 inclusive. `%` is the remainder operator, so `i % 2 == 0` is true for even numbers. `continue` jumps straight to the next iteration. the second statement is an **if-expression**: it produces a value, so it needs no `end`. common mistakes writing `=` where `==` is needed in a comparison. using `while true do` without any `task.wait()`, which freezes the game. forgetting `then` or `end`. a loop that never yields and never ends will hang the script and can freeze the server. always give long-running loops a `task.wait()`. print the numbers 1 to 20, but print "fizz" instead for multiples of 3.','2026-11-22');
INSERT OR REPLACE INTO entry_sources (entry_id,source_id) VALUES ('luau-control-flow','luau-syntax');
INSERT OR REPLACE INTO knowledge_items (id,package_id,kind,title,path,category,level,summary,tags,version,status,origin,search_text,updated_at) VALUES ('luau-tables','rdev-luau','lesson','Tables: arrays and dictionaries','Luau Programming','Luau Programming','Beginner','Use tables to hold lists and key-value data, and loop over them with ipairs and pairs.','luau,table,array,dictionary,ipairs','1.0.0','published','ai-assisted','tables: arrays and dictionaries use tables to hold lists and key-value data, and loop over them with ipairs and pairs. the **table** is luau''s only built-in collection. as an *array* it holds ordered values starting at index 1. as a *dictionary* it maps keys to values. example  how it works `#items` is the array length; indexes start at 1, not 0. `table.find` returns the index of a value, or `nil`. `ipairs` visits array entries in order. `pairs` visits every key, in no guaranteed order. common mistakes using index 0 and expecting it to be the first item. relying on `pairs` order for gameplay logic. removing items from an array while looping forwards over it. use `table.clone` to copy a table and `table.freeze` to make a table read-only when it holds fixed configuration. make a dictionary of three item names to prices. loop over it and print the name and price, then print the total cost.','2026-11-22');
