INSERT OR REPLACE INTO entry_sources (entry_id,source_id) VALUES ('luau-tables','luau-syntax');
INSERT OR REPLACE INTO knowledge_items (id,package_id,kind,title,path,category,level,summary,tags,version,status,origin,search_text,updated_at) VALUES ('luau-modulescripts','rdev-luau','lesson','Organizing code with ModuleScripts','Luau Programming','Luau Programming','Intermediate','Share reusable code between scripts with ModuleScripts and require.','luau,modulescript,require,organization,table','1.0.0','published','ai-assisted','organizing code with modulescripts share reusable code between scripts with modulescripts and require. a **modulescript** returns exactly one value, usually a table of functions. any script can `require` it. the first `require` runs the module and caches the result, so later calls get the same table. example   how it works the module builds a table, adds functions and returns it. `require` gives the caller that table. server and client each run their own copy of a shared module. common mistakes forgetting the `return` at the end of the module. two modules that require each other, which creates a circular dependency. keeping secrets in a module under replicatedstorage; clients can read it. anything in replicatedstorage is visible to clients. keep server-only modules in serverstorage or serverscriptservice. create a module with `add` and `subtract` functions, require it from two scripts, and print results from both.','2026-11-22');
INSERT OR REPLACE INTO entry_sources (entry_id,source_id) VALUES ('luau-modulescripts','class-modulescript');
