INSERT OR REPLACE INTO knowledge_items (id,package_id,kind,title,path,category,level,summary,tags,version,status,origin,search_text,updated_at) VALUES ('ref-script-types','rdev-luau','reference','Script, LocalScript and ModuleScript','Luau Programming','Reference','Beginner','What each script type does and where it can run.','script,localscript,modulescript,server,client','1.0.0','published','ai-assisted','script, localscript and modulescript what each script type does and where it can run. there are three script types. summary **script**: runs on the server by default. its `runcontext` property can instead make it run on the client. **localscript**: runs on a client, in locations such as starterplayerscripts, startergui and a player''s backpack or character. **modulescript**: does not run by itself. it returns a value (usually a table) to whichever script calls `require` on it.  the server and each client keep a separate copy of a module''s cached result.','2026-11-22');
