INSERT OR REPLACE INTO knowledge_items (id,package_id,kind,title,path,category,level,summary,tags,version,status,origin,search_text,updated_at) VALUES ('ref-luau-syntax','rdev-luau','reference','Luau syntax cheat sheet','Luau Programming','Reference','Beginner','Operators, string tools and syntax features you will use daily.','luau,syntax,string,operators,cheatsheet','1.0.0','published','ai-assisted','luau syntax cheat sheet operators, string tools and syntax features you will use daily. a quick reminder of luau basics. operators arithmetic: `+ - * / // % ^`. `//` is floor division. comparison: `== ~= < <= > >=`. not-equal is `~=`. logic: `and`, `or`, `not`. text joining: `..`. length: `#`. compound assignment: `+= -= *= /= //= %= ^= ..=`. strings interpolation: `` `hello {name}` `` `string.format("%d / %d", a, b)`, `string.sub`, `string.split`, `string.upper`.  comments start with `--`. block comments use `--[[ ... ]]`.','2026-11-22');
