INSERT OR REPLACE INTO rlf_packages (id,title,version,checksum,entry_count,body,updated_at) VALUES ('rdev-luau','Luau Programming','1.0.0','7e4663a194757ed7e23243f1d7315c6ef1dc9be493e62a61c3ca6093a828b355',7,'{"format":"rlf","formatVersion":1,"id":"rdev-luau","title":"Luau Programming","description":"The language of Roblox: variables, functions, tables, control flow and modules.","version":"1.0.0","license":"All rights reserved by the project owner until a license is selected and published. Linked third-party sources keep their own terms.","entries":[{"id":"luau-variables","kind":"lesson","title":"Variables and basic data types","path":"Luau Programming","category":"Luau Programming","level":"Beginner","minutes":9,"summary":"Store information with local variables and work with strings, numbers and booleans.","tags":["luau","variable","string","number","boolean"],"objectives":["Declare local variables","Recognize common Luau data types","Update values safely"],"prerequisites":[],"order":1,"blocks":[{"type":"p","text":"A **variable** is a named place to keep a value while a script runs. In Luau, prefer `local` variables unless a wider scope is genuinely needed. Luau also supports compound assignment such as `+=` and interpolated strings written with backticks."},{"type":"h","text":"Example","level":2},{"type":"code","lang":"luau","code":"local playerName = \"Alex\"\nlocal coins = 25\nlocal hasJoined = true\n\ncoins += 10\nprint(`{playerName} has {coins} coins`)\nprint(typeof(coins), typeof(hasJoined))"},{"type":"h","text":"How it works","level":2},{"type":"list","ordered":true,"items":["`playerName` holds a string, `coins` a number and `hasJoined` a boolean.","`coins += 10` adds ten to the existing value.","Backtick strings insert values written inside braces.","`typeof` reports the type of a value at runtime."]},{"type":"h","text":"Common mistakes","level":2},{"type":"list","ordered":false,"items":["Using unclear names such as `x` or `data` for everything.","Forgetting `local`, which creates a global variable that other scripts may overwrite.","Joining a number to a string with `+` instead of `..` or interpolation."]},{"type":"callout","tone":"note","text":"`nil` means \"no value\". Reading a variable that was never set gives `nil`, not an error."},{"type":"exercise","text":"Create variables for a player name, a score and whether a round is active. Print all three with one interpolated string, then add 5 to the score and print again."}],"sourceIds":["luau-syntax","luau-home"],"status":"published","origin":"ai-assisted","review":null,"version":"1.0.0","updatedAt":"2026-11-22"},{"id":"luau-functions","kind":"lesson","title":"Writing reusable functions","path":"Luau Programming","category":"Luau Programming","level":"Beginner","minutes":8,"summary":"Group instructions into functions and pass information through parameters and return values.","tags":["luau","function","parameter","return"],"objectives":["Define and call a function","Use parameters and return values","Choose descriptive function names"],"prerequisites":["luau-variables"],"order":2,"blocks":[{"type":"p","text":"Functions package instructions so they can be called whenever needed. This removes repetition and gives a script clear structure. **Parameters** are inputs; a **return** statement sends a result back to the caller."},{"type":"h","text":"Example","level":2},{"type":"code","lang":"luau","code":"local function calculateReward(baseReward: number, multiplier: number): number\n    return baseReward * multiplier\nend\n\nlocal reward = calculateReward(50, 2)\nprint(reward) -- 100"},{"type":"h","text":"How it works","level":2},{"type":"list","ordered":true,"items":["The function accepts two parameters. The `: number` parts are optional type annotations that help tooling catch mistakes.","`return` hands the calculated value back.","The call passes 50 and 2, so `reward` becomes 100."]},{"type":"h","text":"Common mistakes","level":2},{"type":"list","ordered":false,"items":["Forgetting to `return` when the caller needs a value.","Writing one huge function that handles unrelated jobs.","Defining a function after the code that calls it when using `local function`."]},{"type":"callout","tone":"tip","text":"Name functions with verbs such as `calculateReward` or `spawnEnemy` so call sites read like sentences."},{"type":"exercise","text":"Write a function `addBonus(score, bonus)` that returns the new total. Call it twice with different values and print both results."}],"sourceIds":["luau-syntax"],"status":"published","origin":"ai-assisted","review":null,"version":"1.0.0","updatedAt":"2026-11-22"},{"id":"luau-control-flow","kind":"lesson","title":"Decisions and loops","path":"Luau Programming","category":"Luau Programming","level":"Beginner","minutes":9,"summary":"Use if statements, numeric for loops, while loops and continue to control how code runs.","tags":["luau","if","loop","control flow","condition"],"objectives":["Write if, elseif and else branches","Repeat work with for and while loops","Skip an iteration with continue"],"prerequisites":["luau-functions"],"order":3,"blocks":[{"type":"p","text":"Control flow decides which code runs and how often. `if` chooses a branch. `for` repeats a known number of times. `while` repeats until a condition becomes false."},{"type":"h","text":"Example","level":2},{"type":"code","lang":"luau","code":"for i = 1, 10 do\n    if i % 2 == 0 then\n        continue -- skip even numbers\n    end\n    print(\"odd:\", i)\nend\n\nlocal health = 35\nlocal state = if health > 50 then \"healthy\" elseif health > 0 then \"hurt\" else \"down\"\nprint(state)"},{"type":"h","text":"How it works","level":2},{"type":"list","ordered":true,"items":["`for i = 1, 10` counts from 1 to 10 inclusive.","`%` is the remainder operator, so `i % 2 == 0` is true for even numbers.","`continue` jumps straight to the next iteration.","The second statement is an **if-expression**: it produces a value, so it needs no `end`."]},{"type":"h","text":"Common mistakes","level":2},{"type":"list","ordered":false,"items":["Writing `=` where `==` is needed in a comparison.","Using `while true do` without any `task.wait()`, which freezes the game.","Forgetting `then` or `end`."]},{"type":"callout","tone":"warning","text":"A loop that never yields and never ends will hang the script and can freeze the server. Always give long-running loops a `task.wait()`."},{"type":"exercise","text":"Print the numbers 1 to 20, but print \"Fizz\" instead for multiples of 3."}],"sourceIds":["luau-syntax"],"status":"published","origin":"ai-assisted","review":null,"version":"1.0.0","updatedAt":"2026-11-22"},{"id":"luau-tables","kind":"lesson","title":"Tables: arrays and dictionaries","path":"Luau Programming","category":"Luau Programming","level":"Beginner","minutes":10,"summary":"Use tables to hold lists and key-value data, and loop over them with ipairs and pairs.","tags":["luau","table","array","dictionary","ipairs"],"objectives":["Create arrays and dictionaries","Add, remove and find items","Choose between ipairs and pairs"],"prerequisites":["luau-control-flow"],"order":4,"blocks":[{"type":"p","text":"The **table** is Luau''s only built-in collection. As an *array* it holds ordered values starting at index 1. As a *dictionary* it maps keys to values."},{"type":"h","text":"Example","level":2},{"type":"code","lang":"luau","code":"local items = { \"Sword\", \"Shield\" }\ntable.insert(items, \"Potion\")\nprint(#items, table.find(items, \"Shield\")) -- 3  2\n\nlocal stats = { health = 100, speed = 16 }\nstats.stamina = 50\n\nfor index, name in ipairs(items) do\n    print(index, name)\nend\n\nfor key, value in pairs(stats) do\n    print(key, value)\nend"},{"type":"h","text":"How it works","level":2},{"type":"list","ordered":true,"items":["`#items` is the array length; indexes start at 1, not 0.","`table.find` returns the index of a value, or `nil`.","`ipairs` visits array entries in order. `pairs` visits every key, in no guaranteed order."]},{"type":"h","text":"Common mistakes","level":2},{"type":"list","ordered":false,"items":["Using index 0 and expecting it to be the first item.","Relying on `pairs` order for gameplay logic.","Removing items from an array while looping forwards over it."]},{"type":"callout","tone":"tip","text":"Use `table.clone` to copy a table and `table.freeze` to make a table read-only when it holds fixed configuration."},{"type":"exercise","text":"Make a dictionary of three item names to prices. Loop over it and print the name and price, then print the total cost."}],"sourceIds":["lib-table","luau-syntax"],"status":"published","origin":"ai-assisted","review":null,"version":"1.0.0","updatedAt":"2026-11-22"},{"id":"luau-modulescripts","kind":"lesson","title":"Organizing code with ModuleScripts","path":"Luau Programming","category":"Luau Programming","level":"Intermediate","minutes":10,"summary":"Share reusable code between scripts with ModuleScripts and require.","tags":["luau","modulescript","require","organization","table"],"objectives":["Create a ModuleScript that returns a table","Load it with require","Know why modules help organize projects"],"prerequisites":["luau-tables"],"order":5,"blocks":[{"type":"p","text":"A **ModuleScript** returns exactly one value, usually a table of functions. Any script can `require` it. The first `require` runs the module and caches the result, so later calls get the same table."},{"type":"h","text":"Example","level":2},{"type":"code","lang":"luau","code":"-- ModuleScript named MathUtil in ReplicatedStorage\nlocal MathUtil = {}\n\nfunction MathUtil.clampPercent(value: number): number\n    return math.clamp(value, 0, 100)\nend\n\nreturn MathUtil"},{"type":"code","lang":"luau","code":"-- Script elsewhere\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal MathUtil = require(ReplicatedStorage:WaitForChild(\"MathUtil\"))\n\nprint(MathUtil.clampPercent(140)) -- 100"},{"type":"h","text":"How it works","level":2},{"type":"list","ordered":true,"items":["The module builds a table, adds functions and returns it.","`require` gives the caller that table.","Server and client each run their own copy of a shared module."]},{"type":"h","text":"Common mistakes","level":2},{"type":"list","ordered":false,"items":["Forgetting the `return` at the end of the module.","Two modules that require each other, which creates a circular dependency.","Keeping secrets in a module under ReplicatedStorage; clients can read it."]},{"type":"callout","tone":"warning","text":"Anything in ReplicatedStorage is visible to clients. Keep server-only modules in ServerStorage or ServerScriptService."},{"type":"exercise","text":"Create a module with `add` and `subtract` functions, require it from two scripts, and print results from both."}],"sourceIds":["class-modulescript","roblox-scripting-docs"],"status":"published","origin":"ai-assisted","review":null,"version":"1.0.0","updatedAt":"2026-11-22"},{"id":"ref-script-types","kind":"reference","title":"Script, LocalScript and ModuleScript","path":"Luau Programming","category":"Reference","level":"Beginner","minutes":4,"summary":"What each script type does and where it can run.","tags":["script","localscript","modulescript","server","client"],"objectives":[],"prerequisites":[],"order":20,"blocks":[{"type":"p","text":"There are three script types."},{"type":"h","text":"Summary","level":2},{"type":"list","ordered":false,"items":["**Script**: runs on the server by default. Its `RunContext` property can instead make it run on the client.","**LocalScript**: runs on a client, in locations such as StarterPlayerScripts, StarterGui and a player''s Backpack or character.","**ModuleScript**: does not run by itself. It returns a value (usually a table) to whichever script calls `require` on it."]},{"type":"code","lang":"luau","code":"local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal Config = require(ReplicatedStorage:WaitForChild(\"Config\"))\nprint(Config.MaxPlayers)"},{"type":"callout","tone":"note","text":"The server and each client keep a separate copy of a module''s cached result."}],"sourceIds":["roblox-scripting-docs","class-modulescript"],"status":"published","origin":"ai-assisted","review":null,"version":"1.0.0","updatedAt":"2026-11-22"},{"id":"ref-luau-syntax","kind":"reference","title":"Luau syntax cheat sheet","path":"Luau Programming","category":"Reference","level":"Beginner","minutes":5,"summary":"Operators, string tools and syntax features you will use daily.","tags":["luau","syntax","string","operators","cheatsheet"],"objectives":[],"prerequisites":[],"order":21,"blocks":[{"type":"p","text":"A quick reminder of Luau basics."},{"type":"h","text":"Operators","level":2},{"type":"list","ordered":false,"items":["Arithmetic: `+ - * / // % ^`. `//` is floor division.","Comparison: `== ~= < <= > >=`. Not-equal is `~=`.","Logic: `and`, `or`, `not`.","Text joining: `..`. Length: `#`.","Compound assignment: `+= -= *= /= //= %= ^= ..=`."]},{"type":"h","text":"Strings","level":2},{"type":"list","ordered":false,"items":["Interpolation: `` `Hello {name}` ``","`string.format(\"%d / %d\", a, b)`, `string.sub`, `string.split`, `string.upper`."]},{"type":"code","lang":"luau","code":"local name = \"Sam\"\nlocal level = 7\nprint(`{name} is level {level}`)\nprint((\"%s has %d points\"):format(name, level * 10))\nprint(#\"abc\", 7 // 2, 7 % 2)"},{"type":"callout","tone":"note","text":"Comments start with `--`. Block comments use `--[[ ... ]]`."}],"sourceIds":["luau-syntax","lib-string"],"status":"published","origin":"ai-assisted","review":null,"version":"1.0.0","updatedAt":"2026-11-22"}],"sources":[{"id":"roblox-scripting-docs","label":"Roblox Creator Hub — Scripting","url":"https://create.roblox.com/docs/scripting","publisher":"Roblox Corporation","license":null,"status":"unchecked","retrievedAt":null,"contentHash":null},{"id":"luau-home","label":"Luau language — Overview","url":"https://luau.org/","publisher":"Luau project","license":null,"status":"unchecked","retrievedAt":null,"contentHash":null},{"id":"luau-syntax","label":"Luau language — Syntax","url":"https://luau.org/syntax","publisher":"Luau project","license":null,"status":"unchecked","retrievedAt":null,"contentHash":null},{"id":"class-modulescript","label":"API reference — ModuleScript","url":"https://create.roblox.com/docs/reference/engine/classes/ModuleScript","publisher":"Roblox Corporation","license":null,"status":"unchecked","retrievedAt":null,"contentHash":null},{"id":"lib-table","label":"API reference — table library","url":"https://create.roblox.com/docs/reference/engine/libraries/table","publisher":"Roblox Corporation","license":null,"status":"unchecked","retrievedAt":null,"contentHash":null},{"id":"lib-string","label":"API reference — string library","url":"https://create.roblox.com/docs/reference/engine/libraries/string","publisher":"Roblox Corporation","license":null,"status":"unchecked","retrievedAt":null,"contentHash":null}],"relationships":[{"from":"luau-control-flow","to":"luau-functions","type":"prerequisite","weight":1,"reason":"Authored prerequisite"},{"from":"luau-functions","to":"luau-variables","type":"prerequisite","weight":1,"reason":"Authored prerequisite"},{"from":"luau-modulescripts","to":"luau-tables","type":"prerequisite","weight":1,"reason":"Authored prerequisite"},{"from":"luau-tables","to":"luau-control-flow","type":"prerequisite","weight":1,"reason":"Authored prerequisite"},{"from":"luau-variables","to":"luau-functions","type":"next","weight":1,"reason":"Next lesson in path"},{"from":"luau-functions","to":"luau-control-flow","type":"next","weight":1,"reason":"Next lesson in path"},{"from":"luau-control-flow","to":"luau-tables","type":"next","weight":1,"reason":"Next lesson in path"},{"from":"luau-tables","to":"luau-modulescripts","type":"next","weight":1,"reason":"Next lesson in path"},{"from":"luau-modulescripts","to":"luau-tables","type":"related","weight":0.25,"reason":"Shared topics: luau, table"},{"from":"luau-modulescripts","to":"pro-project-organization","type":"related","weight":0.25,"reason":"Shared topics: modulescript, organization"},{"from":"luau-tables","to":"luau-modulescripts","type":"related","weight":0.25,"reason":"Shared topics: luau, table"},{"from":"luau-variables","to":"ref-luau-syntax","type":"related","weight":0.25,"reason":"Shared topics: luau, string"},{"from":"ref-luau-syntax","to":"luau-variables","type":"related","weight":0.25,"reason":"Shared topics: luau, string"},{"from":"ref-script-types","to":"backend-client-server","type":"related","weight":0.43,"reason":"Shared topics: localscript, server, client"},{"from":"ref-script-types","to":"ref-remote-api","type":"related","weight":0.25,"reason":"Shared topics: server, client"},{"from":"ref-script-types","to":"backend-remote-events","type":"related","weight":0.22,"reason":"Shared topics: server, client"}],"checksum":"7e4663a194757ed7e23243f1d7315c6ef1dc9be493e62a61c3ca6093a828b355"}','2026-11-22');
