INSERT OR REPLACE INTO knowledge_items (id,package_id,kind,title,path,category,level,summary,tags,version,status,origin,search_text,updated_at) VALUES ('ui-basics','rdev-ui','lesson','Building a simple interface','UI/UX Development','UI/UX Development','Beginner','Understand ScreenGui, Frame, TextLabel and TextButton, and how scale and offset size things.','ui,screengui,frame,textbutton,scale,offset','1.0.0','published','ai-assisted','building a simple interface understand screengui, frame, textlabel and textbutton, and how scale and offset size things. interfaces are commonly built with a **screengui** inside startergui. each player receives a copy when they join. **frames** group elements, **textlabels** show text and **textbuttons** are clickable. sizes use **udim2**, which has a *scale* part (a fraction of the parent) and an *offset* part (pixels). scale adapts to different screens; offset is exact. example  how it works `udim2.new(0.5, 0, 0, 48)` means width scale 0.5 and offset 0, height scale 0 and offset 48. a localscript runs on the player''s device, so it can change that player''s interface. `activated` fires for mouse clicks, taps and gamepad presses. common mistakes testing at only one resolution. using tiny text or low-contrast colors. using `mousebutton1click` only, which is less friendly to touch and gamepad than `activated`. use the device emulator in studio''s test tab to preview phone and tablet screens. create a centered panel with a heading and a button. preview it on a phone-sized emulator and a desktop viewport and note anything that breaks.','2026-11-22');
