INSERT OR REPLACE INTO knowledge_items (id,package_id,kind,title,path,category,level,summary,tags,version,status,origin,search_text,updated_at) VALUES ('ui-layout','rdev-ui','lesson','Responsive layout with UIListLayout and constraints','UI/UX Development','UI/UX Development','Beginner','Let Roblox arrange your interface with layout objects instead of positioning every element by hand.','ui,uilistlayout,uipadding,uiaspectratioconstraint,layout,responsive','1.0.0','published','ai-assisted','responsive layout with uilistlayout and constraints let roblox arrange your interface with layout objects instead of positioning every element by hand. layout objects are children of a container that arrange its other children automatically. **uilistlayout** stacks items vertically or horizontally, **uipadding** adds space inside the container, and **uiaspectratioconstraint** keeps a shape from stretching on wide or tall screens. example  how it works the list arranges buttons top to bottom, with 8 pixels between them. `sortorder = layoutorder` lets you control order with each element''s `layoutorder` property. each button is the full width of the menu and a comfortable 44 pixels tall for touch. common mistakes fighting a layout by setting `position` on its children; the layout will override it. making buttons smaller than a fingertip. aim for at least 44 pixels in height. combine a scale width with a fixed pixel height for buttons that fit any screen while staying easy to tap. build a vertical menu with three buttons using uilistlayout and uipadding. check that nothing overlaps on a phone emulator.','2026-11-22');
