INSERT OR REPLACE INTO knowledge_items (id,package_id,kind,title,path,category,level,summary,tags,version,status,origin,search_text,updated_at) VALUES ('ui-buttons-input','rdev-ui','lesson','Buttons, feedback and touch-friendly input','UI/UX Development','UI/UX Development','Intermediate','Make interfaces respond clearly to presses on touch, mouse and gamepad.','ui,textbutton,activated,touch,feedback,tweenservice','1.0.0','published','ai-assisted','buttons, feedback and touch-friendly input make interfaces respond clearly to presses on touch, mouse and gamepad. players use phones, tablets, consoles and desktops. a good interface works on all of them. prefer **activated** over mouse-specific events, and never make an important action available only on hover, because touch screens have no hover. example  how it works activated runs for every input type. a short tween changes the color so the player sees that the press registered. `task.delay` schedules the color to return after 0.15 seconds. common mistakes providing no feedback, so players tap repeatedly. hiding information in tooltips that appear only on hover. placing buttons at the very edge where thumbs or system gestures interfere. add pressed feedback to three buttons. then disable a button for one second after use to prevent accidental double taps.','2026-11-22');
