INSERT OR REPLACE INTO knowledge_items (id,package_id,kind,title,path,category,level,summary,tags,version,status,origin,search_text,updated_at) VALUES ('ref-ui-objects','rdev-ui','reference','Interface objects quick reference','UI/UX Development','Reference','Beginner','The objects you combine to build an on-screen interface.','ui,screengui,frame,textlabel,textbutton,uilistlayout','1.0.0','published','ai-assisted','interface objects quick reference the objects you combine to build an on-screen interface. containers and content **screengui**: the top-level container that displays on a player''s screen. **frame**: a rectangle that groups other elements. **textlabel**: shows text. **textbutton**: shows text and can be pressed. **imagelabel** and **imagebutton**: the same with images. **scrollingframe**: a frame whose content can scroll. layout helpers **uilistlayout** and **uigridlayout** arrange children. **uipadding** adds inner space. **uicorner** rounds corners. **uiaspectratioconstraint** and **uisizeconstraint** keep sizes sensible. **uiscale** scales an element and its children together. ','2026-11-22');
