INSERT OR REPLACE INTO rlf_packages (id,title,version,checksum,entry_count,body,updated_at) VALUES ('rdev-ui','UI/UX Development','1.0.0','177c13a0fa025b23da6e52bca67b82f6d91d49e513f8a48aeec0b07459908bef',4,'{"format":"rlf","formatVersion":1,"id":"rdev-ui","title":"UI/UX Development","description":"Build responsive interfaces that work on phones, tablets and desktops.","version":"1.0.0","license":"All rights reserved by the project owner until a license is selected and published. Linked third-party sources keep their own terms.","entries":[{"id":"ui-basics","kind":"lesson","title":"Building a simple interface","path":"UI/UX Development","category":"UI/UX Development","level":"Beginner","minutes":10,"summary":"Understand ScreenGui, Frame, TextLabel and TextButton, and how scale and offset size things.","tags":["ui","screengui","frame","textbutton","scale","offset"],"objectives":["Describe the role of ScreenGui","Build a simple panel hierarchy","Use scale and offset intentionally"],"prerequisites":[],"order":1,"blocks":[{"type":"p","text":"Interfaces are commonly built with a **ScreenGui** inside StarterGui. Each player receives a copy when they join. **Frames** group elements, **TextLabels** show text and **TextButtons** are clickable."},{"type":"p","text":"Sizes use **UDim2**, which has a *scale* part (a fraction of the parent) and an *offset* part (pixels). Scale adapts to different screens; offset is exact."},{"type":"h","text":"Example","level":2},{"type":"code","lang":"luau","code":"-- LocalScript inside a TextButton inside a Frame inside a ScreenGui\nlocal button = script.Parent\nbutton.Text = \"Start\"\nbutton.Size = UDim2.new(0.5, 0, 0, 48) -- half the parent''s width, 48 pixels tall\n\nbutton.Activated:Connect(function()\n    print(\"Start pressed\")\nend)"},{"type":"h","text":"How it works","level":2},{"type":"list","ordered":true,"items":["`UDim2.new(0.5, 0, 0, 48)` means width scale 0.5 and offset 0, height scale 0 and offset 48.","A LocalScript runs on the player''s device, so it can change that player''s interface.","`Activated` fires for mouse clicks, taps and gamepad presses."]},{"type":"h","text":"Common mistakes","level":2},{"type":"list","ordered":false,"items":["Testing at only one resolution.","Using tiny text or low-contrast colors.","Using `MouseButton1Click` only, which is less friendly to touch and gamepad than `Activated`."]},{"type":"callout","tone":"tip","text":"Use the device emulator in Studio''s Test tab to preview phone and tablet screens."},{"type":"exercise","text":"Create a centered panel with a heading and a button. Preview it on a phone-sized emulator and a desktop viewport and note anything that breaks."}],"sourceIds":["roblox-ui-docs","datatype-udim2"],"status":"published","origin":"ai-assisted","review":null,"version":"1.0.0","updatedAt":"2026-11-22"},{"id":"ui-layout","kind":"lesson","title":"Responsive layout with UIListLayout and constraints","path":"UI/UX Development","category":"UI/UX Development","level":"Beginner","minutes":9,"summary":"Let Roblox arrange your interface with layout objects instead of positioning every element by hand.","tags":["ui","uilistlayout","uipadding","uiaspectratioconstraint","layout","responsive"],"objectives":["Stack elements with UIListLayout","Add spacing with UIPadding","Keep proportions with UIAspectRatioConstraint"],"prerequisites":["ui-basics"],"order":2,"blocks":[{"type":"p","text":"Layout objects are children of a container that arrange its other children automatically. **UIListLayout** stacks items vertically or horizontally, **UIPadding** adds space inside the container, and **UIAspectRatioConstraint** keeps a shape from stretching on wide or tall screens."},{"type":"h","text":"Example","level":2},{"type":"code","lang":"luau","code":"local function addMenuButton(menu: Frame, label: string)\n    local button = Instance.new(\"TextButton\")\n    button.Text = label\n    button.Size = UDim2.new(1, 0, 0, 44)\n    button.Parent = menu\n    return button\nend\n\nlocal menu = script.Parent\nlocal list = Instance.new(\"UIListLayout\")\nlist.Padding = UDim.new(0, 8)\nlist.SortOrder = Enum.SortOrder.LayoutOrder\nlist.Parent = menu\n\naddMenuButton(menu, \"Play\")\naddMenuButton(menu, \"Settings\")"},{"type":"h","text":"How it works","level":2},{"type":"list","ordered":true,"items":["The list arranges buttons top to bottom, with 8 pixels between them.","`SortOrder = LayoutOrder` lets you control order with each element''s `LayoutOrder` property.","Each button is the full width of the menu and a comfortable 44 pixels tall for touch."]},{"type":"h","text":"Common mistakes","level":2},{"type":"list","ordered":false,"items":["Fighting a layout by setting `Position` on its children; the layout will override it.","Making buttons smaller than a fingertip. Aim for at least 44 pixels in height."]},{"type":"callout","tone":"tip","text":"Combine a scale width with a fixed pixel height for buttons that fit any screen while staying easy to tap."},{"type":"exercise","text":"Build a vertical menu with three buttons using UIListLayout and UIPadding. Check that nothing overlaps on a phone emulator."}],"sourceIds":["class-uilistlayout","roblox-ui-docs"],"status":"published","origin":"ai-assisted","review":null,"version":"1.0.0","updatedAt":"2026-11-22"},{"id":"ui-buttons-input","kind":"lesson","title":"Buttons, feedback and touch-friendly input","path":"UI/UX Development","category":"UI/UX Development","level":"Intermediate","minutes":10,"summary":"Make interfaces respond clearly to presses on touch, mouse and gamepad.","tags":["ui","textbutton","activated","touch","feedback","tweenservice"],"objectives":["Handle presses with Activated","Give visible feedback","Avoid hover-only interactions"],"prerequisites":["ui-layout"],"order":3,"blocks":[{"type":"p","text":"Players use phones, tablets, consoles and desktops. A good interface works on all of them. Prefer **Activated** over mouse-specific events, and never make an important action available only on hover, because touch screens have no hover."},{"type":"h","text":"Example","level":2},{"type":"code","lang":"luau","code":"local TweenService = game:GetService(\"TweenService\")\n\nlocal button = script.Parent\nlocal normal = button.BackgroundColor3\nlocal pressed = Color3.fromRGB(70, 70, 70)\nlocal info = TweenInfo.new(0.12)\n\nbutton.Activated:Connect(function()\n    TweenService:Create(button, info, { BackgroundColor3 = pressed }):Play()\n    task.delay(0.15, function()\n        TweenService:Create(button, info, { BackgroundColor3 = normal }):Play()\n    end)\n    print(\"Button used\")\nend)"},{"type":"h","text":"How it works","level":2},{"type":"list","ordered":true,"items":["Activated runs for every input type.","A short tween changes the color so the player sees that the press registered.","`task.delay` schedules the color to return after 0.15 seconds."]},{"type":"h","text":"Common mistakes","level":2},{"type":"list","ordered":false,"items":["Providing no feedback, so players tap repeatedly.","Hiding information in tooltips that appear only on hover.","Placing buttons at the very edge where thumbs or system gestures interfere."]},{"type":"exercise","text":"Add pressed feedback to three buttons. Then disable a button for one second after use to prevent accidental double taps."}],"sourceIds":["roblox-ui-docs","class-tweenservice"],"status":"published","origin":"ai-assisted","review":null,"version":"1.0.0","updatedAt":"2026-11-22"},{"id":"ref-ui-objects","kind":"reference","title":"Interface objects quick reference","path":"UI/UX Development","category":"Reference","level":"Beginner","minutes":4,"summary":"The objects you combine to build an on-screen interface.","tags":["ui","screengui","frame","textlabel","textbutton","uilistlayout"],"objectives":[],"prerequisites":[],"order":20,"blocks":[{"type":"h","text":"Containers and content","level":2},{"type":"list","ordered":false,"items":["**ScreenGui**: the top-level container that displays on a player''s screen.","**Frame**: a rectangle that groups other elements.","**TextLabel**: shows text. **TextButton**: shows text and can be pressed.","**ImageLabel** and **ImageButton**: the same with images.","**ScrollingFrame**: a frame whose content can scroll."]},{"type":"h","text":"Layout helpers","level":2},{"type":"list","ordered":false,"items":["**UIListLayout** and **UIGridLayout** arrange children.","**UIPadding** adds inner space.","**UICorner** rounds corners.","**UIAspectRatioConstraint** and **UISizeConstraint** keep sizes sensible.","**UIScale** scales an element and its children together."]},{"type":"code","lang":"luau","code":"local gui = Instance.new(\"ScreenGui\")\ngui.ResetOnSpawn = false\ngui.Parent = game:GetService(\"Players\").LocalPlayer:WaitForChild(\"PlayerGui\")"}],"sourceIds":["roblox-ui-docs","class-uilistlayout"],"status":"published","origin":"ai-assisted","review":null,"version":"1.0.0","updatedAt":"2026-11-22"}],"sources":[{"id":"roblox-ui-docs","label":"Roblox Creator Hub — User interface","url":"https://create.roblox.com/docs/ui","publisher":"Roblox Corporation","license":null,"status":"unchecked","retrievedAt":null,"contentHash":null},{"id":"class-tweenservice","label":"API reference — TweenService","url":"https://create.roblox.com/docs/reference/engine/classes/TweenService","publisher":"Roblox Corporation","license":null,"status":"unchecked","retrievedAt":null,"contentHash":null},{"id":"class-uilistlayout","label":"API reference — UIListLayout","url":"https://create.roblox.com/docs/reference/engine/classes/UIListLayout","publisher":"Roblox Corporation","license":null,"status":"unchecked","retrievedAt":null,"contentHash":null},{"id":"datatype-udim2","label":"API reference — UDim2","url":"https://create.roblox.com/docs/reference/engine/datatypes/UDim2","publisher":"Roblox Corporation","license":null,"status":"unchecked","retrievedAt":null,"contentHash":null}],"relationships":[{"from":"ui-buttons-input","to":"ui-layout","type":"prerequisite","weight":1,"reason":"Authored prerequisite"},{"from":"ui-layout","to":"ui-basics","type":"prerequisite","weight":1,"reason":"Authored prerequisite"},{"from":"ui-basics","to":"ui-layout","type":"next","weight":1,"reason":"Next lesson in path"},{"from":"ui-layout","to":"ui-buttons-input","type":"next","weight":1,"reason":"Next lesson in path"},{"from":"ui-basics","to":"ref-ui-objects","type":"related","weight":0.5,"reason":"Shared topics: ui, screengui, frame, textbutton"},{"from":"ui-basics","to":"ui-buttons-input","type":"related","weight":0.2,"reason":"Shared topics: ui, textbutton"},{"from":"ui-buttons-input","to":"ref-ui-objects","type":"related","weight":0.2,"reason":"Shared topics: ui, textbutton"},{"from":"ui-buttons-input","to":"ui-basics","type":"related","weight":0.2,"reason":"Shared topics: ui, textbutton"},{"from":"ui-layout","to":"ref-ui-objects","type":"related","weight":0.2,"reason":"Shared topics: ui, uilistlayout"},{"from":"ref-ui-objects","to":"ui-basics","type":"related","weight":0.5,"reason":"Shared topics: ui, screengui, frame, textbutton"},{"from":"ref-ui-objects","to":"ui-buttons-input","type":"related","weight":0.2,"reason":"Shared topics: ui, textbutton"},{"from":"ref-ui-objects","to":"ui-layout","type":"related","weight":0.2,"reason":"Shared topics: ui, uilistlayout"}],"checksum":"177c13a0fa025b23da6e52bca67b82f6d91d49e513f8a48aeec0b07459908bef"}','2026-11-22');
